def unique_sorted(xs):
    return sorted(set(xs))

assert unique_sorted([3, 1, 3, 2, 1]) == [1, 2, 3]
assert unique_sorted([]) == []

zig_test:
test "t06 unicos ordenados" {
    const a = [_]i32{ 3, 1, 3, 2, 1 };
    const out = try uniqueSorted(std.testing.allocator, &a);
    defer std.testing.allocator.free(out);
    try std.testing.expectEqualSlices(i32, &[_]i32{ 1, 2, 3 }, out);
    const empty = [_]i32{};
    const out2 = try uniqueSorted(std.testing.allocator, &empty);
    defer std.testing.allocator.free(out2);
    try std.testing.expectEqual(@as(usize, 0), out2.len);
}
